using sv_4c708767091145f08727521b75402bb9.Client.Models;
using sv_4c708767091145f08727521b75402bb9.Client.Services;

namespace sv_4c708767091145f08727521b75402bb9.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
