                    Description = "Package picked up",
                    Location = "Los Angeles, CA"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 7, 11, 14, 30, 0, TimeSpan.FromHours(-6)),
                    Description = "Arrived at sorting facility",
                    Location = "Denver, CO"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 7, 13, 9, 15, 0, TimeSpan.FromHours(-5)),
                    Description = "In transit to destination",
                    Location = "Chicago, IL"
                }
            ]
        },
        ["PKG-002"] = new Shipment
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "New York, NY",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 12, 12, 0, 0, TimeSpan.FromHours(-4)),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 7, 8, 10, 0, 0, TimeSpan.FromHours(-4)),
                    Description = "Package picked up",
                    Location = "Boston, MA"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 7, 10, 6, 45, 0, TimeSpan.FromHours(-4)),
                    Description = "Out for delivery",
                    Location = "New York, NY"
                },
                new StatusUpdate
                {
                    Timestamp = new DateTimeOffset(2026, 7, 10, 14, 22, 0, TimeSpan.FromHours(-4)),
                    Description = "Delivered — signed by J. Smith",
                    Location = "New York, NY"
                }
            ]
        },
        ["PKG-003"] = new Shipment
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Seattle, WA",
            EstimatedDelivery = new DateTimeOffset(2026, 7, 22, 18, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates =
            [
