using System.Net;
using System.Net.Http.Json;
using sv_4c708767091145f08727521b75402bb9.Client.Models;

namespace sv_4c708767091145f08727521b75402bb9.Client.Services;

public sealed class ClientShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var encodedTracking = Uri.EscapeDataString(trackingNumber);
        var response = await httpClient.GetAsync($"api/shipments/{encodedTracking}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<Shipment>(ct);
    }
}

